css:
.loader {
  position: relative;
  width: 48px;
  height: 48px;
}
.loader i {
  position: absolute;
  border-radius: 50%;
  border: 3px solid #6366f1;
  box-sizing: border-box;
}
.loader i:nth-child(1) { inset: 0; animation: g1 1.4s linear infinite; }
.loader i:nth-child(2) { inset: 6px; border-color: #818cf8; animation: g2 1.4s linear infinite; }
.loader i:nth-child(3) { inset: 12px; animation: g3 1.4s linear infinite; }
@keyframes g1 {
  0%, 100% { transform: rotate(0deg) scaleX(1); }
  50% { transform: rotate(180deg) scaleX(0.2); }
}
@keyframes g2 {
  0%, 100% { transform: scaleY(1); }
  50% { transform: scaleY(0.2); }
}
@keyframes g3 {
  0%, 100% { transform: scaleX(1) rotate(0deg); }
  50% { transform: scaleX(0.2) rotate(-180deg); }
}
